CREATE TABLE rt_payment_intents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES rt_orders(id) ON DELETE RESTRICT, mode varchar(16) NOT NULL CHECK(mode IN ('separate','combined')), provider varchar(80), currency char(3) NOT NULL REFERENCES rt_currencies(code), requested_amount numeric(20,6) NOT NULL CHECK(requested_amount>0), captured_amount numeric(20,6) NOT NULL DEFAULT 0 CHECK(captured_amount>=0), refunded_amount numeric(20,6) NOT NULL DEFAULT 0 CHECK(refunded_amount>=0), status varchar(32) NOT NULL DEFAULT 'created', idempotency_key_id uuid REFERENCES rt_idempotency_keys(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(refunded_amount<=captured_amount));
ALTER TABLE rt_reconciliation_cases ADD CONSTRAINT rt_reconciliation_payment_fk FOREIGN KEY(payment_intent_id) REFERENCES rt_payment_intents(id) ON DELETE RESTRICT;
CREATE TABLE rt_payment_allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_intent_id uuid NOT NULL REFERENCES rt_payment_intents(id) ON DELETE RESTRICT, booking_id uuid NOT NULL REFERENCES rt_bookings(id) ON DELETE RESTRICT, amount numeric(20,6) NOT NULL CHECK(amount>0), currency char(3) NOT NULL REFERENCES rt_currencies(code), status varchar(24) NOT NULL DEFAULT 'reserved', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(payment_intent_id,booking_id));
CREATE INDEX rt_payment_allocations_booking_idx ON rt_payment_allocations(booking_id);
CREATE TABLE rt_provider_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_intent_id uuid NOT NULL REFERENCES rt_payment_intents(id) ON DELETE RESTRICT, provider varchar(80) NOT NULL, external_transaction_id varchar(255), transaction_type varchar(24) NOT NULL, amount numeric(20,6) NOT NULL CHECK(amount>=0), currency char(3) NOT NULL REFERENCES rt_currencies(code), status varchar(24) NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,external_transaction_id));
CREATE TABLE rt_credit_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES rt_companies(id) ON DELETE RESTRICT, currency char(3) NOT NULL REFERENCES rt_currencies(code), credit_limit numeric(20,6) NOT NULL DEFAULT 0 CHECK(credit_limit>=0), status varchar(24) NOT NULL DEFAULT 'pending', version integer NOT NULL DEFAULT 1, UNIQUE(company_id,currency));
CREATE TABLE rt_balance_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES rt_companies(id) ON DELETE RESTRICT, currency char(3) NOT NULL REFERENCES rt_currencies(code), status varchar(24) NOT NULL DEFAULT 'active', UNIQUE(company_id,currency));
CREATE TABLE rt_financial_reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES rt_bookings(id) ON DELETE RESTRICT, credit_account_id uuid REFERENCES rt_credit_accounts(id) ON DELETE RESTRICT, balance_account_id uuid REFERENCES rt_balance_accounts(id) ON DELETE RESTRICT, amount numeric(20,6) NOT NULL CHECK(amount>0), currency char(3) NOT NULL REFERENCES rt_currencies(code), state varchar(24) NOT NULL DEFAULT 'held', expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), released_at timestamptz, CHECK((credit_account_id IS NOT NULL) <> (balance_account_id IS NOT NULL)));
CREATE INDEX rt_financial_reservations_booking_idx ON rt_financial_reservations(booking_id,state);
CREATE TABLE rt_financial_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid REFERENCES rt_bookings(id) ON DELETE RESTRICT, payment_intent_id uuid REFERENCES rt_payment_intents(id) ON DELETE RESTRICT, reservation_id uuid REFERENCES rt_financial_reservations(id) ON DELETE RESTRICT, company_id uuid REFERENCES rt_companies(id) ON DELETE RESTRICT, movement_type varchar(40) NOT NULL, amount numeric(20,6) NOT NULL CHECK(amount>0), currency char(3) NOT NULL REFERENCES rt_currencies(code), external_key varchar(160), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(external_key));
CREATE TABLE rt_refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES rt_bookings(id) ON DELETE RESTRICT, payment_intent_id uuid NOT NULL REFERENCES rt_payment_intents(id) ON DELETE RESTRICT, amount numeric(20,6) NOT NULL CHECK(amount>0), currency char(3) NOT NULL REFERENCES rt_currencies(code), status varchar(32) NOT NULL DEFAULT 'requested', reason text, provider_ref varchar(255), requested_by bigint REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE rt_invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid REFERENCES rt_companies(id) ON DELETE RESTRICT, order_id uuid REFERENCES rt_orders(id) ON DELETE RESTRICT, invoice_no varchar(80) NOT NULL UNIQUE, currency char(3) NOT NULL REFERENCES rt_currencies(code), total numeric(20,6) NOT NULL CHECK(total>=0), status varchar(24) NOT NULL DEFAULT 'draft', issued_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rt_invoice_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES rt_invoices(id) ON DELETE RESTRICT, booking_id uuid NOT NULL REFERENCES rt_bookings(id) ON DELETE RESTRICT, description text NOT NULL, amount numeric(20,6) NOT NULL, currency char(3) NOT NULL REFERENCES rt_currencies(code));
CREATE TABLE rt_supplier_settlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id uuid NOT NULL REFERENCES rt_suppliers(id) ON DELETE RESTRICT, currency char(3) NOT NULL REFERENCES rt_currencies(code), period_from date NOT NULL, period_to date NOT NULL, status varchar(24) NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now(), CHECK(period_to>=period_from));
CREATE TABLE rt_supplier_settlement_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), settlement_id uuid NOT NULL REFERENCES rt_supplier_settlements(id) ON DELETE RESTRICT, booking_id uuid NOT NULL REFERENCES rt_bookings(id) ON DELETE RESTRICT, amount numeric(20,6) NOT NULL, currency char(3) NOT NULL REFERENCES rt_currencies(code), UNIQUE(settlement_id,booking_id));
